	cmd.Flags().StringVar(&bodySsidRadiusPolicies, "ssid-radius-policies", "", "RADIUS policies")
	cmd.Flags().StringVar(&bodySsidRadiusProxy, "ssid-radius-proxy", "", "RADIUS proxy settings")
	cmd.Flags().StringVar(&bodySsidRadiusServers, "ssid-radius-servers", "", "Organization RADIUS servers, ordered by priority")
	cmd.Flags().StringVar(&bodySsidRadiusTesting, "ssid-radius-testing", "", "RADIUS testing settings")
	cmd.Flags().StringVar(&bodySsidSecurityEncryption, "ssid-security-encryption", "", "Encryption settings for the SSID")
	cmd.Flags().StringVar(&bodySsidSecurityIdentityPassphrase, "ssid-security-identity-passphrase", "", "Identity passphrase settings")
	cmd.Flags().StringVar(&bodySsidSecurityMode, "ssid-security-mode", "", "Security mode of the SSID")
	cmd.Flags().StringVar(&bodySsidSecurityProtocol, "ssid-security-protocol", "", "Security protocol used by the SSID")
	cmd.Flags().StringVar(&bodySsidSplashAuth, "ssid-splash-auth", "", "Authentication-related splash settings")
	cmd.Flags().StringVar(&bodySsidSplashCaptivePortal, "ssid-splash-captive-portal", "", "Captive portal configuration")
